using System.Text.Json;
using TabletopRpg.Core;

namespace TabletopRpg.PlayerAgent;

/// <summary>
/// Strict, fail-closed parsing of untrusted model output. Identity is supplied by
/// the runtime, never by text generated by a model. It cannot define DCs, HP or outcomes.
/// </summary>
public static class PlayerIntentDecoder
{
    public static GameIntent? TryDecode(
        string? response,
        ParticipantId participantId,
        CharacterId characterId)
    {
        if (string.IsNullOrWhiteSpace(response) || response.Length > 4_096 ||
            participantId.Value == Guid.Empty || characterId.Value == Guid.Empty)
            return null;

        try
        {
            using var document = JsonDocument.Parse(response, new JsonDocumentOptions
            {
                CommentHandling = JsonCommentHandling.Disallow,
                AllowTrailingCommas = false,
                MaxDepth = 4
            });
            var root = document.RootElement;
            if (root.ValueKind != JsonValueKind.Object) return null;

            var fields = root.EnumerateObject().ToArray();
            if (fields.Length is < 1 or > 2 ||
                fields.Select(p => p.Name).Distinct(StringComparer.Ordinal).Count() != fields.Length)
                return null;

            foreach (var field in fields)
                if (field.Name is not ("kind" or "text")) return null;

            if (!root.TryGetProperty("kind", out var kind) ||
                kind.ValueKind != JsonValueKind.String)
                return null;

            return kind.GetString() switch
            {
                "speak" when fields.Length == 2 &&
                    root.TryGetProperty("text", out var text) &&
                    text.ValueKind == JsonValueKind.String &&
                    !string.IsNullOrWhiteSpace(text.GetString()) &&
                    text.GetString()!.Length <= 1_000 =>
                    new SpeakIntent(participantId, characterId, text.GetString()!.Trim()),
                "end_turn" when fields.Length == 1 =>
                    new EndCombatTurnIntent(participantId, characterId),
                "pass" when fields.Length == 1 => null,
                _ => null
            };
        }
        catch (JsonException)
        {
            return null;
        }
    }
}
